Repair the following complete CommonJS module. Return a corrected complete source file.

`applySettingsPatch(current, patch, expectedRevision)` uses optimistic revision matching. `current` must contain exactly usable fields `revision` and `settings`, where `revision` is a non-negative safe integer and `settings` has a string `theme` and boolean `notifications`. `expectedRevision` must be a non-negative safe integer. `patch` must be a non-null, non-array object containing only optional `theme` and `notifications` fields with the same respective types. Invalid input must throw `TypeError`.

If revisions differ, return `{ applied: false, value }`; otherwise apply the patch, increment the revision by one, and return `{ applied: true, value }`. Throw `RangeError` if incrementing would exceed the safe-integer range. An empty patch still increments a matching revision. In all cases, `value` and `value.settings` must be fresh, and neither input may be mutated or aliased. Export exactly `{ applySettingsPatch }`.

Known-bad source:
```javascript
function validateCurrent(current) {
  if (!current || typeof current !== 'object' || Array.isArray(current) ||
      !Number.isSafeInteger(current.revision) || current.revision < 0 ||
      !current.settings || typeof current.settings !== 'object' || Array.isArray(current.settings) ||
      typeof current.settings.theme !== 'string' ||
      typeof current.settings.notifications !== 'boolean') {
    throw new TypeError('invalid current settings');
  }
}

function applySettingsPatch(current, patch, expectedRevision) {
  validateCurrent(current);
  if (!patch || typeof patch !== 'object' || Array.isArray(patch) ||
      !Number.isSafeInteger(expectedRevision) || expectedRevision < 0) {
    throw new TypeError('invalid input');
  }
  for (const key of Object.keys(patch)) {
    if ((key !== 'theme' && key !== 'notifications') ||
        (key === 'theme' && typeof patch[key] !== 'string') ||
        (key === 'notifications' && typeof patch[key] !== 'boolean')) {
      throw new TypeError('invalid patch');
    }
  }

  if (current.revision !== expectedRevision) {
    return {
      applied: false,
      value: { revision: current.revision, settings: { ...current.settings } }
    };
  }
  if (current.revision === Number.MAX_SAFE_INTEGER) throw new RangeError('revision overflow');

  const settings = current.settings;
  if (Object.prototype.hasOwnProperty.call(patch, 'theme')) settings.theme = patch.theme;
  if (Object.prototype.hasOwnProperty.call(patch, 'notifications')) settings.notifications = patch.notifications;
  return {
    applied: true,
    value: { revision: current.revision + 1, settings }
  };
}

module.exports = { applySettingsPatch };
```

