'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['applySettingsPatch']);
const { applySettingsPatch } = api;

const current = Object.freeze({
  revision: 4,
  settings: Object.freeze({ theme: 'dark', notifications: true })
});
const patch = Object.freeze({ theme: '', notifications: false });
const applied = applySettingsPatch(current, patch, 4);
assert.deepEqual(applied, {
  applied: true,
  value: { revision: 5, settings: { theme: '', notifications: false } }
});
assert.notStrictEqual(applied.value, current);
assert.notStrictEqual(applied.value.settings, current.settings);
assert.deepEqual(current, { revision: 4, settings: { theme: 'dark', notifications: true } });
assert.deepEqual(patch, { theme: '', notifications: false });

const mismatch = applySettingsPatch(current, { theme: 'light' }, 3);
assert.deepEqual(mismatch, {
  applied: false,
  value: { revision: 4, settings: { theme: 'dark', notifications: true } }
});
assert.notStrictEqual(mismatch.value, current);
assert.notStrictEqual(mismatch.value.settings, current.settings);

const emptyPatch = applySettingsPatch(current, {}, 4);
assert.deepEqual(emptyPatch, {
  applied: true,
  value: { revision: 5, settings: { theme: 'dark', notifications: true } }
});
assert.notStrictEqual(emptyPatch.value.settings, current.settings);

assert.throws(() => applySettingsPatch({
  revision: Number.MAX_SAFE_INTEGER,
  settings: { theme: 'x', notifications: false }
}, {}, Number.MAX_SAFE_INTEGER), RangeError);

for (const badCurrent of [
  null,
  [],
  {},
  { revision: -1, settings: { theme: 'x', notifications: true } },
  { revision: 1.5, settings: { theme: 'x', notifications: true } },
  { revision: 0, settings: null },
  { revision: 0, settings: { theme: 1, notifications: true } },
  { revision: 0, settings: { theme: 'x', notifications: 1 } }
]) {
  assert.throws(() => applySettingsPatch(badCurrent, {}, 0), TypeError);
}
for (const badPatch of [null, [], 'x', { other: true }, { theme: 1 }, { notifications: 1 }]) {
  assert.throws(() => applySettingsPatch(current, badPatch, 4), TypeError);
}
for (const revision of [-1, 1.5, NaN, Infinity, Number.MAX_SAFE_INTEGER + 1, '4']) {
  assert.throws(() => applySettingsPatch(current, {}, revision), TypeError);
}

